if($page==='login'){ if(current_user()) redirect('index.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ if(Auth::login(post('email'),post('password'))) redirect('index.php'); $error='E-mail ou senha inválidos.'; } ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entrar · Inova CRM</title><?=favicon_tags()?><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><div class="login-card"><img src="assets/logo-inova-crm.png" alt="Inova CRM" class="login-logo"><p class="tagline">Conecte. Organize. Cresça.</p><h1>Bem-vindo de volta</h1><?php if($error): ?><div class="flash error"><?=e($error)?></div><?php endif; ?><form method="post"><label>E-mail<input type="email" name="email" required autofocus></label><label>Senha<input type="password" name="password" required></label><button class="btn primary">Entrar no painel</button></form><p class="hint">Configure o banco e crie o primeiro administrador conforme o README.</p></div></body></html><?php exit; }
require_login(); if($page==='admin') require_admin();
